"use client"

import * as React from "react"
import {
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from "@tanstack/react-table"
import { useVirtualizer } from "@tanstack/react-virtual"
import { parseISO } from "date-fns"
import { SortVerticalIcon } from "@solar-icons/react/linear"
import { cn } from "cn"

import { formatDate, formatTHB } from "@/lib/format"
import { statusLabel, type Order } from "@/lib/demo-data"
import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"

const ROW_HEIGHT = 40
const nf = new Intl.NumberFormat("th-TH")

const sortable = (label: string, align?: "right") =>
  function SortableHeader({ column }: { column: { toggleSorting: (desc?: boolean) => void; getIsSorted: () => false | "asc" | "desc" } }) {
    return (
      <Button
        variant="ghost"
        size="sm"
        onClick={() => column.toggleSorting(column.getIsSorted() === "asc")}
        className={cn("-mx-2 text-muted-foreground", align === "right" && "ml-auto flex")}
      >
        {label}
        <SortVerticalIcon className="size-3.5" />
      </Button>
    )
  }

const columns: ColumnDef<Order>[] = [
  { accessorKey: "id", header: "เลขที่", size: 130, cell: ({ getValue }) => <span className="font-mono text-xs">{String(getValue())}</span> },
  { accessorKey: "customer", header: sortable("ลูกค้า"), size: 220 },
  { accessorKey: "status", header: "สถานะ", size: 120, cell: ({ row }) => statusLabel[row.original.status] },
  { accessorKey: "channel", header: "ช่องทาง", size: 110 },
  {
    accessorKey: "date",
    header: sortable("วันที่"),
    size: 120,
    cell: ({ row }) => formatDate(parseISO(row.original.date), { style: "short" }),
  },
  {
    accessorKey: "amount",
    header: sortable("ยอดเงิน", "right"),
    size: 120,
    cell: ({ row }) => <div className="text-right tabular-nums">{formatTHB(row.original.amount)}</div>,
  },
]

/**
 * Block: virtualized table for thousands of rows — only the rows in view are
 * in the DOM (≈ 20 instead of 10,000). Sticky header, fixed 40px rows,
 * sorting, no pagination and **no row animations** (they fight the
 * virtualizer). Use it when people scan/scroll a long list; for filtering and
 * bulk actions on a page of results, use the Data Table block.
 */
export function VirtualTable({ data, height = 480 }: { data: Order[]; height?: number }) {
  const [sorting, setSorting] = React.useState<SortingState>([])
  const scrollRef = React.useRef<HTMLDivElement>(null)

  // eslint-disable-next-line react-hooks/incompatible-library
  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })
  const rows = table.getRowModel().rows

  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => ROW_HEIGHT,
    overscan: 8,
  })
  const items = virtualizer.getVirtualItems()
  // Spacer rows keep real <table> layout (column widths, borders) while skipping off-screen rows
  const padTop = items[0]?.start ?? 0
  const padBottom = virtualizer.getTotalSize() - (items.at(-1)?.end ?? 0)

  return (
    <Card className="gap-0 overflow-hidden py-0">
      <div className="flex items-center justify-between border-b p-3 text-sm text-muted-foreground">
        <span className="tabular-nums">{nf.format(rows.length)} รายการ</span>
        <span className="hidden sm:inline">เลื่อนเพื่อดูเพิ่ม — แสดงผลเฉพาะแถวที่อยู่บนจอ</span>
      </div>
      {/* the scroll container must be the table's direct scroller, or the sticky header breaks */}
      <div
        ref={scrollRef}
        role="region"
        aria-label="ตารางคำสั่งซื้อทั้งหมด"
        tabIndex={0}
        className="relative overflow-auto outline-none focus-visible:ring-3 focus-visible:ring-ring/50"
        style={{ height }}
      >
        <table data-slot="table" className="w-full min-w-[820px] table-fixed text-sm" aria-rowcount={rows.length + 1}>
          <thead className="sticky top-0 z-10 bg-card shadow-[inset_0_-1px_0_var(--border)]">
            {table.getHeaderGroups().map((hg) => (
              <tr key={hg.id} aria-rowindex={1}>
                {hg.headers.map((h) => (
                  <th
                    key={h.id}
                    style={{ width: h.getSize() }}
                    className="h-10 bg-muted/40 px-3 text-left align-middle font-medium whitespace-nowrap text-muted-foreground"
                  >
                    {h.isPlaceholder ? null : flexRender(h.column.columnDef.header, h.getContext())}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {padTop > 0 && (
              <tr aria-hidden>
                <td colSpan={columns.length} style={{ height: padTop }} />
              </tr>
            )}
            {items.map((v) => {
              const row = rows[v.index]
              return (
                <tr
                  key={row.id}
                  aria-rowindex={v.index + 2}
                  style={{ height: ROW_HEIGHT }}
                  className="border-b transition-colors hover:bg-muted/50"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id} className="truncate px-3 align-middle">
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              )
            })}
            {padBottom > 0 && (
              <tr aria-hidden>
                <td colSpan={columns.length} style={{ height: padBottom }} />
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </Card>
  )
}

/** Synthetic sample data for the /demo dashboard and gallery previews. Not real customers. */

export type OrderStatus = "paid" | "pending" | "shipped" | "refunded"

export type Order = {
  id: string
  customer: string
  email: string
  status: OrderStatus
  channel: "Web" | "LINE OA" | "Shopee" | "Lazada"
  amount: number
  date: string // ISO 8601, e.g. "2026-09-28"
}

const customers = [
  ["สมชาย ใจดี", "somchai@example.com"],
  ["Nattaya K.", "nattaya@example.com"],
  ["บริษัท ทองไทย จำกัด", "billing@thongthai.example"],
  ["Pimchanok S.", "pim@example.com"],
  ["วิภาวดี รุ่งเรือง", "wipa@example.com"],
  ["Ekkachai P.", "ekkachai@example.com"],
  ["ร้านกาแฟดอยสูง", "hello@doisoong.example"],
  ["Thanakorn W.", "thanakorn@example.com"],
  ["มาลี ศรีสุข", "malee@example.com"],
  ["Kittipong L.", "kittipong@example.com"],
  ["สุดารัตน์ แสงทอง", "sudarat@example.com"],
  ["Arunee C.", "arunee@example.com"],
] as const

const statuses: OrderStatus[] = ["paid", "paid", "shipped", "pending", "paid", "refunded", "shipped", "paid"]
const channels: Order["channel"][] = ["Web", "LINE OA", "Shopee", "Lazada"]

/** The data "ends" here; demo date presets are relative to it so they always have rows. */
export const DEMO_TODAY = new Date(2026, 8, 30)

/** Local YYYY-MM-DD, `n` days before DEMO_TODAY */
function daysAgo(n: number) {
  const d = new Date(DEMO_TODAY)
  d.setDate(d.getDate() - n)
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
}

export const orders: Order[] = Array.from({ length: 60 }, (_, i) => {
  const [customer, email] = customers[i % customers.length]
  return {
    id: `ORD-${24081 + i * 7}`,
    customer,
    email,
    status: statuses[(i * 3) % statuses.length],
    channel: channels[(i * 5) % channels.length],
    amount: Math.round((((i * 7919) % 9000) + 350) / 10) * 10,
    date: daysAgo((i * 3) % 89),
  }
})

/** Deterministic bulk sample (e.g. 10,000 rows for the virtualized table) — same shape as `orders` */
export function makeOrders(count: number): Order[] {
  return Array.from({ length: count }, (_, i) => {
    const [customer, email] = customers[(i * 7) % customers.length]
    return {
      id: `ORD-${String(100001 + i)}`,
      customer,
      email,
      status: statuses[(i * 5) % statuses.length],
      channel: channels[(i * 3) % channels.length],
      amount: Math.round((((i * 7919) % 12000) + 120) / 10) * 10,
      date: daysAgo((i * 13) % 365),
    }
  })
}

export const statusLabel: Record<OrderStatus, string> = {
  paid: "ชำระแล้ว",
  pending: "รอชำระ",
  shipped: "จัดส่งแล้ว",
  refunded: "คืนเงิน",
}

export const kpis = [
  { key: "revenue", label: "รายได้เดือนนี้", value: 1284500, delta: 12.4, format: { style: "currency", currency: "THB", maximumFractionDigits: 0 }, trend: [38, 41, 39, 44, 47, 45, 52, 55, 53, 58, 61, 64] },
  { key: "orders", label: "คำสั่งซื้อ", value: 3421, delta: 8.1, format: {}, trend: [210, 230, 225, 260, 255, 270, 290, 285, 300, 310, 305, 330] },
  { key: "customers", label: "ลูกค้าใหม่", value: 482, delta: -3.2, format: {}, trend: [52, 49, 51, 47, 45, 46, 43, 44, 41, 42, 40, 39] },
  { key: "aov", label: "ยอดเฉลี่ยต่อออเดอร์", value: 375.4, delta: 4.6, format: { style: "currency", currency: "THB", maximumFractionDigits: 0 }, trend: [350, 355, 352, 360, 358, 362, 365, 361, 368, 370, 372, 375] },
] as const satisfies ReadonlyArray<{ key: string; label: string; value: number; delta: number; format: Intl.NumberFormatOptions; trend: readonly number[] }>

export const revenueSeries = Array.from({ length: 90 }, (_, i) => {
  const base = 32000 + Math.sin(i / 3) * 6000 + i * 140
  return {
    date: daysAgo(89 - i),
    web: Math.round(base * 0.55),
    marketplace: Math.round(base * 0.45 + Math.cos(i / 2) * 2500),
  }
})

/**
 * Ecsight formatters — the one place dates, money and relative times are
 * turned into Thai copy. `th-TH` uses the Buddhist calendar (พ.ศ.) and Arabic
 * digits by default; pass `era: "ce"` for ค.ศ.
 */

type Era = "be" | "ce"
type DateInput = Date | string | number

const localeFor = (era: Era) => (era === "ce" ? "th-TH-u-ca-gregory" : "th-TH")
const toDate = (d: DateInput) => (d instanceof Date ? d : new Date(d))

const dateStyles = {
  /** 1 ต.ค. 69 */
  short: { day: "numeric", month: "short", year: "2-digit" },
  /** 1 ต.ค. 2569 */
  medium: { day: "numeric", month: "short", year: "numeric" },
  /** 1 ตุลาคม 2569 */
  long: { day: "numeric", month: "long", year: "numeric" },
} satisfies Record<string, Intl.DateTimeFormatOptions>

export type DateStyle = keyof typeof dateStyles

export function formatDate(d: DateInput, { style = "medium", era = "be" }: { style?: DateStyle; era?: Era } = {}) {
  return toDate(d).toLocaleDateString(localeFor(era), dateStyles[style])
}

/** "1–7 ต.ค. 2569", "28 ก.ย. – 4 ต.ค. 2569" — collapses shared month/year. */
export function formatDateRange(from: DateInput, to: DateInput, { era = "be" }: { era?: Era } = {}) {
  return new Intl.DateTimeFormat(localeFor(era), dateStyles.medium).formatRange(toDate(from), toDate(to))
}

/** 14:05 */
export function formatTime(d: DateInput) {
  return toDate(d).toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" })
}

const thb = new Intl.NumberFormat("th-TH", { style: "currency", currency: "THB", maximumFractionDigits: 0 })
const thbSatang = new Intl.NumberFormat("th-TH", { style: "currency", currency: "THB", minimumFractionDigits: 2 })

/** ฿1,284,500 — pass `satang: true` for ฿1,284,500.00 */
export function formatTHB(n: number, { satang = false }: { satang?: boolean } = {}) {
  return (satang ? thbSatang : thb).format(n)
}

const relative = new Intl.RelativeTimeFormat("th", { numeric: "auto" })
const units: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 31_536_000],
  ["month", 2_592_000],
  ["week", 604_800],
  ["day", 86_400],
  ["hour", 3_600],
  ["minute", 60],
]

/** "3 นาทีที่ผ่านมา", "เมื่อวาน", "ในอีก 2 วัน"; under a minute → "เมื่อสักครู่". */
export function formatRelative(d: DateInput, now: DateInput = Date.now()) {
  const seconds = (toDate(d).getTime() - toDate(now).getTime()) / 1000
  for (const [unit, size] of units) {
    if (Math.abs(seconds) >= size) return relative.format(Math.round(seconds / size), unit)
  }
  return "เมื่อสักครู่"
}

/* ─── Date ↔ string for APIs and inputs ──────────────────────────────── */

const pad = (n: number) => String(n).padStart(2, "0")

/**
 * "2026-10-01" from the **local** calendar day. Use this for API payloads and
 * URLs — `date.toISOString()` goes through UTC, so local midnight in Thailand
 * (UTC+7) would come out as the previous day.
 */
export function toISODate(d: Date) {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** "2026-10-01" → local midnight (not UTC, unlike `new Date("2026-10-01")`). Invalid → undefined. */
export function parseISODate(s: string) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s)
  return m ? safeDate(Number(m[1]), Number(m[2]), Number(m[3])) : undefined
}

function safeDate(y: number, m: number, d: number) {
  const date = new Date(y, m - 1, d)
  return date.getFullYear() === y && date.getMonth() === m - 1 && date.getDate() === d ? date : undefined
}

// Thai month names as Intl prints them — short ("ต.ค.") and long ("ตุลาคม"), dots optional
const thaiMonths = Array.from({ length: 12 }, (_, m) => {
  const d = new Date(2026, m, 1)
  return [d.toLocaleDateString("th-TH", { month: "short" }), d.toLocaleDateString("th-TH", { month: "long" })].map(
    (s) => s.replace(/\./g, "")
  )
})

/** Resolve a typed year: ≥ 2400 is พ.ศ.; 2 digits follow `era` (69 → 2569 → 2026, or 26 → 2026). */
function toCE(year: string, era: Era) {
  const y = Number(year)
  if (year.length <= 2) return era === "be" ? 2500 + y - 543 : 2000 + y
  return y >= 2400 ? y - 543 : y
}

/**
 * Parse what people actually type into a date field. Accepts Thai or Arabic
 * digits, พ.ศ. or ค.ศ. (a 4-digit year ≥ 2400 is พ.ศ.), and:
 * `1/10/2569` · `01-10-69` · `1.10.2026` · `01102569` · `1 ต.ค. 2569` · `1 ตุลาคม 69` · `2026-10-01`.
 * Returns local midnight, or undefined when the text isn't a real date.
 */
export function parseThaiDate(input: string, { era = "be" }: { era?: Era } = {}): Date | undefined {
  const s = input
    .trim()
    .replace(/[๐-๙]/g, (c) => String(c.charCodeAt(0) - 0x0e50))
    .replace(/\s+/g, " ")
  if (!s) return undefined

  const iso = parseISODate(s)
  if (iso) return iso

  let m = /^(\d{1,2})[/\-. ](\d{1,2})[/\-. ](\d{2}|\d{4})$/.exec(s)
  if (m) return safeDate(toCE(m[3], era), Number(m[2]), Number(m[1]))

  m = /^(\d{2})(\d{2})(\d{2}|\d{4})$/.exec(s)
  if (m) return safeDate(toCE(m[3], era), Number(m[2]), Number(m[1]))

  m = /^(\d{1,2}) ?([ก-๛.]+) ?(\d{2}|\d{4})$/.exec(s)
  if (m) {
    const name = m[2].replace(/\./g, "")
    const month = thaiMonths.findIndex((names) => names.includes(name))
    if (month >= 0) return safeDate(toCE(m[3], era), month + 1, Number(m[1]))
  }
  return undefined
}
